mapper.select:
SELECT p.id AS productId, p.name AS productName, ps.thumb_img AS thumbImg, SUM(oi.sku_num) AS totalSales, SUM(oi.sku_price * oi.sku_num) AS totalAmount FROM order_item oi INNER JOIN order_info o ON oi.order_id = o.id INNER JOIN product_sku ps ON oi.sku_id = ps.id INNER JOIN product p ON ps.product_id = p.id WHERE o.order_status IN (1, 2, 3) AND oi.is_deleted = 0 AND o.is_deleted = 0 AND ps.is_deleted = 0 AND p.is_deleted = 0
AND o.create_time >= #{dto.createTimeBegin}
AND o.create_time <= #{dto.createTimeEnd}
GROUP BY p.id, p.name, ps.thumb_img ORDER BY totalSales DESC LIMIT #{dto.limit}

SELECT p.category3_id AS categoryId, c.name AS categoryName, SUM(oi.sku_num) AS totalSales, SUM(oi.sku_price * oi.sku_num) AS totalAmount FROM order_item oi INNER JOIN order_info o ON oi.order_id = o.id INNER JOIN product_sku ps ON oi.sku_id = ps.id INNER JOIN product p ON ps.product_id = p.id LEFT JOIN category c ON p.category3_id = c.id WHERE o.order_status IN (1, 2, 3) AND oi.is_deleted = 0 AND o.is_deleted = 0 AND ps.is_deleted = 0 AND p.is_deleted = 0
AND o.create_time >= #{dto.createTimeBegin}
AND o.create_time <= #{dto.createTimeEnd}
GROUP BY p.category3_id, c.name ORDER BY totalAmount DESC
